{
  "schemaVersion": "2.0.0",
  "skills": [
    {
      "schemaVersion": "2.0.0",
      "skillId": "independent-deliberation-panel",
      "version": "1.0.0",
      "path": "./independent-deliberation-panel",
      "enabled": true,
      "priority": 10,
      "providers": [
        {
          "capabilities": [
            "independent-deliberation",
            "independent-review",
            "cross-examination",
            "evidence-resolution",
            "consensus-decision"
          ],
          "executionClass": "workflow",
          "phase": "decision-analysis",
          "phaseOrder": 40,
          "requiredInputArtifacts": [
            "case-brief",
            "evidence-sources",
            "constraints"
          ],
          "inputBindings": [
            {
              "targetArtifact": "case-brief",
              "sources": [
                "task-envelope",
                "bootstrap:task-contract-report"
              ],
              "operation": "combine"
            },
            {
              "targetArtifact": "evidence-sources",
              "sources": [
                "task:user-evidence",
                "bootstrap:instruction-scope-resolution",
                "bootstrap:workspace-convention-profile"
              ],
              "operation": "collect"
            },
            {
              "targetArtifact": "constraints",
              "sources": [
                "task-envelope:constraints",
                "task-envelope:authorization"
              ],
              "operation": "combine"
            }
          ],
          "producedArtifacts": [
            "panel-manifest",
            "cross-examination-plan",
            "issue-ledger",
            "consensus-proposal",
            "decision-record"
          ],
          "outputSchema": "contracts/freeform-output.v1.schema.json",
          "resultSchema": "contracts/provider-result.v1.schema.json",
          "stateMapping": {
            "default": {
              "state": "passed",
              "errorRequired": false
            },
            "adapterErrors": [
              "INVALID_INPUT",
              "MISSING_EVIDENCE"
            ]
          },
          "selectionCriteria": [
            "decision-conflict",
            "high-impact-uncertainty",
            "explicit-independent-review"
          ],
          "preconditions": [
            "The request contains material uncertainty, conflicting requirements, or high failure cost.",
            "A case brief and directly inspectable evidence or evidence locations are available."
          ],
          "failureHandling": "Preserve unresolved claims and return a structured non-passing result when consensus cannot advance.",
          "gate": {
            "kind": "none",
            "policy": "none",
            "validator": "skills/independent-deliberation-panel/contracts/decision-record.v1.schema.json"
          }
        }
      ]
    },
    {
      "schemaVersion": "2.0.0",
      "skillId": "coordinate-subagents",
      "version": "1.1.0",
      "path": "./coordinate-subagents",
