              "operation": "select"
            },
            {
              "targetArtifact": "execution-unit-inventory",
              "sources": [
                "task-envelope:work-units"
              ],
              "operation": "select"
            },
            {
              "targetArtifact": "constraints",
              "sources": [
                "task-envelope:constraints",
                "task-envelope:authorization",
                "bootstrap:instruction-scope-resolution"
              ],
              "operation": "combine"
            }
          ],
          "producedArtifacts": [
            "delegation-decision",
            "task-graph",
            "assignment-briefs",
            "integration-report"
          ],
          "outputSchema": "contracts/freeform-output.v1.schema.json",
          "resultSchema": "contracts/provider-result.v1.schema.json",
          "stateMapping": {
            "default": {
              "state": "passed",
              "errorRequired": false
            },
            "adapterErrors": [
              "INVALID_INPUT",
              "MISSING_EVIDENCE"
            ]
          },
          "selectionCriteria": [
            "explicit-task-decomposition-or-delegation",
            "documented-net-benefit-delegation",
            "explicit-ownership-or-evidence-integration"
          ],
          "preconditions": [
            "The user authorizes the requested work and applicable permission boundaries are known.",
            "The task explicitly requires one of this provider's capabilities. Subagent dispatch additionally requires an explicit user request or a documented net benefit."
          ],
          "failureHandling": "Return the completed assignments and explicitly identify unavailable delegation or audit capacity.",
          "gate": {
            "kind": "none",
            "policy": "none",
            "validator": null
          }
        }
      ]
    },
    {
      "schemaVersion": "2.0.0",
      "skillId": "independent-audit-gate",
      "version": "1.0.0",
      "path": "./independent-audit-gate",
      "enabled": true,
      "priority": 90,
      "providers": [
        {
          "capabilities": [
            "independent-audit",
            "risk-classification",
            "evidence-verification",
            "release-gate"
          ],
          "executionClass": "workflow",
          "phase": "completion-gate",
          "phaseOrder": 90,
          "requiredInputArtifacts": [
            "final-target-identifier",
            "final-diff-or-artifact-digest",
            "raw-verification-results",
            "rollback-or-recovery-evidence"
          ],
          "inputBindings": [
            {
              "targetArtifact": "final-target-identifier",
              "sources": [
                "acceptance-evidence-report:target",
                "workflow:current-target"
              ],
              "operation": "select"
            },
            {
              "targetArtifact": "final-diff-or-artifact-digest",
              "sources": [
                "acceptance-evidence-report:target-digest",
                "change-scope-report:final-digest"
              ],
              "operation": "combine"
            },
            {
              "targetArtifact": "raw-verification-results",
              "sources": [
                "verified-evidence-index:locators"
              ],
              "operation": "collect"
            },
            {
              "targetArtifact": "rollback-or-recovery-evidence",
              "sources": [
                "recovery-evidence",
                "workflow:rollback-evidence"
              ],
              "operation": "require-external"
            }
          ],
          "producedArtifacts": [
            "audit-target",
            "audit-findings",
            "re-audit-status",
            "gate-verdict"
          ],
          "outputSchema": "contracts/freeform-output.v1.schema.json",
          "resultSchema": "contracts/provider-result.v1.schema.json",
          "stateMapping": {
            "selector": "/output/gateVerdict",
            "values": {
              "PASS": {
                "state": "passed",
                "errorRequired": false
              },
              "FAIL": {
                "state": "failed",
                "errorRequired": true,
                "allowedErrorCodes": [
                  "GATE_FAILED"
                ]
              },
              "BLOCKED": {
                "state": "blocked",
                "errorRequired": true,
                "allowedErrorCodes": [
                  "MISSING_EVIDENCE"
                ]
              }
            },
            "default": "reject",
            "adapterErrors": [
              "INVALID_INPUT",
              "MISSING_EVIDENCE"
            ]
          },
          "selectionCriteria": [
            "high-risk-change",
            "final-target-available",
            "explicit-audit-gate"
          ],
          "preconditions": [
            "A final target identifier and final change or release artifact are fixed.",
            "Implementation verification evidence and a fresh auditor independent from implementation are available."
          ],
          "failureHandling": "Return FAIL for blocking findings and BLOCKED when independence or required evidence cannot be confirmed.",
          "gate": {
            "kind": "completion",
            "policy": "mandatory",
            "validator": "independent-audit"
          }
        }
      ]
    },
    {
      "schemaVersion": "2.0.0",
      "skillId": "task-contract",
      "version": "1.1.0",
      "path": "./task-contract",
      "enabled": true,
      "priority": 50,
      "providers": [
        {
