          "outputSchema": "skills/task-contract/contracts/task-contract-report.v1.schema.json",
          "resultSchema": "skills/task-contract/integration/provider-result.v1.schema.json",
          "stateMapping": {
            "selector": "/output/verdict",
            "values": {
              "PASS": {
                "state": "passed",
                "errorRequired": false
              },
              "NEEDS_INPUT": {
                "state": "needs-input",
                "errorRequired": false
              },
              "BLOCKED": {
                "state": "blocked",
                "errorRequired": true,
                "allowedErrorCodes": [
                  "MISSING_EVIDENCE",
                  "INVALID_INPUT"
                ]
              }
            },
            "default": "reject",
            "adapterErrors": [
              "INVALID_INPUT",
              "MISSING_EVIDENCE"
            ]
          },
          "selectionCriteria": [
            "unstructured-task-request",
            "missing-acceptance-criteria",
            "scope-or-authorization-ambiguity",
            "explicit-task-contract"
          ],
          "preconditions": [
            "The user request and applicable instruction resolution are available."
          ],
          "failureHandling": "Return NEEDS_INPUT for material ambiguity and BLOCKED when required source evidence cannot be validated.",
          "gate": {
            "kind": "none",
            "policy": "none",
            "validator": null
          }
        }
      ]
    },
